/* data/cs-c/cs-12-09.js - GENERATED by tools/build.py from data/cs/cs-12-09.json. Questions are the board's; answers are our own words. Do not edit. */
(window.CS_C = window.CS_C || {})["cs-12-09"] = [{"id":"cs-12-09-01","kind":"short","q":"What is Networking ? List advantages of Networking.","marks":4,"src":["Guide ch.9 Networking Technology, Q.1"],"model":[{"t":"Networking means joining two or more computers so that they can share data and resources.","m":1},{"t":"Resource sharing: many users share one printer, one disk and the same software.","m":1},{"t":"Communication: e-mail, chat and file transfer between users; data is shared and kept in one place.","m":1},{"t":"It saves cost, makes backup easy to manage, and increases reliability because data can be kept on more than one computer.","m":1}]},{"id":"cs-12-09-02","kind":"short","q":"What are transmission media ? List characteristics of transmission media.","marks":4,"src":["Guide ch.9 Networking Technology, Q.2"],"model":[{"t":"Transmission media are the paths through which data signals travel from one computer to another: cables or the air.","m":1},{"t":"They are of two kinds: bound (wired) media such as twisted pair, coaxial cable and fiber optic cable, and unbound (wireless) media such as radio waves, microwaves and infrared.","m":1},{"t":"Characteristics: cost, speed (bandwidth) and the maximum distance the signal can go.","m":1},{"t":"Other characteristics: attenuation (weakening of the signal), protection against interference (noise) and ease of installation.","m":1}]},{"id":"cs-12-09-03","kind":"short","q":"What is multiplexing ? Discuss FDM and TDM.","marks":5,"src":["Guide ch.9 Networking Technology, Q.3"],"model":[{"t":"Multiplexing means sending many signals together over one communication channel, which saves the cost of many separate lines.","m":1},{"t":"FDM, frequency division multiplexing: the bandwidth of the channel is divided into frequency bands and each signal gets its own band, used at the same time. Radio and cable TV use it.","m":1},{"t":"TDM, time division multiplexing: each signal gets the whole channel for a short time slot in turn, again and again, so the signals are sent one after another in very quick turns.","m":1},{"t":"FDM is used for analog signals and TDM for digital signals.","m":1},{"t":"At the receiving end a demultiplexer separates the signals again.","m":1}]},{"id":"cs-12-09-04","kind":"short","q":"What are two types of twisted pair media ?","marks":3,"src":["Guide ch.9 Networking Technology, Q.4"],"model":[{"t":"Unshielded twisted pair (UTP): wires twisted in pairs with only a plastic cover; it is cheap and easy to install, but it picks up more noise.","m":1},{"t":"Shielded twisted pair (STP): the pairs have an extra metal shield (foil or braid) around them; it is better against interference, but costs more and is thicker.","m":1},{"t":"Both are made of copper wires twisted in pairs, which reduces interference between the wires.","m":1}]},{"id":"cs-12-09-05","kind":"short","q":"What are different types of coaxial cable ?","marks":3,"src":["Guide ch.9 Networking Technology, Q.5"],"model":[{"t":"Thinnet (thin coaxial cable, RG-58, used in 10BASE2): thin and flexible, up to about 185 metres per segment.","m":1},{"t":"Thicknet (thick coaxial cable, used in 10BASE5): thick and stiff, up to 500 metres per segment, used as a backbone.","m":1},{"t":"A coaxial cable has a central copper wire, an insulator, a metal shield and an outer cover.","m":1}]},{"id":"cs-12-09-06","kind":"short","q":"What are advantages and disadvantages of fiber optic cable ?","marks":4,"src":["Guide ch.9 Networking Technology, Q.6"],"model":[{"t":"Advantage: it carries data as light, so it is not affected by electrical noise or interference.","m":1},{"t":"Advantage: very high speed and bandwidth, and the signal can go a long distance with little loss; it is also hard to tap, so it is secure.","m":1},{"t":"Disadvantage: it is costly, and the cable and the connectors are expensive.","m":1},{"t":"Disadvantage: it is difficult to install and join, and it is fragile compared with copper cable.","m":1}]},{"id":"cs-12-09-07","kind":"short","q":"What are the reasons a wireless media would be chosen over a bound media ?","marks":4,"src":["Guide ch.9 Networking Technology, Q.7"],"model":[{"t":"Where cables cannot be laid easily: across a road, a river, between two buildings or in rough hills.","m":1},{"t":"Mobility: users can move about with their computers and phones and stay connected.","m":1},{"t":"Quick and cheap to set up, as no digging or cable laying is needed; it is good for temporary networks.","m":1},{"t":"It can reach many users at once (broadcast) and cover a wide area, such as a city or a campus.","m":1}]},{"id":"cs-12-09-08","kind":"short","q":"What is topology ? Differentiate between logical and physical topology.","marks":4,"src":["Guide ch.9 Networking Technology, Q.8"],"model":[{"t":"Topology is the way the computers and cables of a network are arranged, such as bus, star and ring.","m":1},{"t":"Physical topology is the real layout: the way the cables join the devices, as one would see it.","m":1},{"t":"Logical topology is the path that the data follows from one device to another, and the way the devices get access to the medium.","m":1},{"t":"The two can be different: a token ring network is wired as a star (physical) but passes data in a ring (logical).","m":1}]},{"id":"cs-12-09-09","kind":"short","q":"What is access method ? State three types of media access methods.","marks":4,"src":["Guide ch.9 Networking Technology, Q.9"],"model":[{"t":"An access method is the rule that decides which computer may send data on the shared medium and when, so that the data of two computers do not mix.","m":1},{"t":"Contention method: any computer sends when the line is free; if two send together there is a collision and they try again (CSMA/CD in Ethernet).","m":1},{"t":"Token passing: a computer may send only when it holds the token that goes round the network.","m":1},{"t":"Polling: a central computer asks each computer in turn if it has data to send.","m":1}]},{"id":"cs-12-09-10","kind":"short","q":"Explain when token passing access method is more appropriate.","marks":3,"src":["Guide ch.9 Networking Technology, Q.10"],"model":[{"t":"Token passing is better when the network carries heavy traffic, because only one computer sends at a time, so there are no collisions.","m":1},{"t":"It is suitable when each computer must get its turn within a known time (a predictable response), as in real time work.","m":1},{"t":"It also suits a network where many computers send long data one after another.","m":1}]},{"id":"cs-12-09-11","kind":"short","q":"Explain the difference between a physical bus topology and physical star topology.","marks":5,"src":["Guide ch.9 Networking Technology, Q.11"],"model":[{"t":"In the bus topology all computers are connected to one common cable (the backbone) with a terminator at both ends. In the star topology every computer is connected by its own cable to a central hub or switch.","m":1},{"t":"Bus needs less cable and is cheap. Star needs more cable and a hub, so it costs more.","m":1},{"t":"In a bus a break in the main cable stops the whole network; in a star the failure of one cable stops only that computer.","m":1},{"t":"Faults are hard to find in a bus and easy to find in a star, because each cable can be tested alone.","m":1},{"t":"Adding a computer is easy in both, but a star can be extended more easily; if the hub fails the whole star stops.","m":1}]},{"id":"cs-12-09-12","kind":"short","q":"What is Network architecture ?","marks":3,"src":["Guide ch.9 Networking Technology, Q.12"],"model":[{"t":"Network architecture is the complete design of a network: the topology, the access method, the type of cables and the protocols used.","m":1},{"t":"It decides how the computers are connected and how they talk to each other.","m":1},{"t":"Examples: Ethernet (bus or star with contention) and Token Ring.","m":1}]},{"id":"cs-12-09-13","kind":"short","q":"Write rules for 10 BASE T network.","marks":4,"src":["Guide ch.9 Networking Technology, Q.13"],"model":[{"t":"10BASE-T works at 10 Mbps, uses baseband signals, and uses twisted pair cable (T stands for twisted pair).","m":1},{"t":"It uses a star topology with a hub at the centre, and each computer is joined to the hub by its own cable.","m":1},{"t":"The cable between a computer and the hub is UTP (category 3 or better) with RJ-45 connectors, and it can be at most 100 metres long.","m":1},{"t":"Hubs can be joined to extend the network, but at most four hubs (repeaters) may be in the path between two computers.","m":1}]},{"id":"cs-12-09-14","kind":"short","q":"Explain the process of passing data on token rings.","marks":5,"src":["Guide ch.9 Networking Technology, Q.14"],"model":[{"t":"A small frame called the token goes round the ring from one computer to the next, in one direction.","m":1},{"t":"A computer that wants to send data waits for the free token, takes it, and attaches its data and the address of the receiver.","m":1},{"t":"The frame goes round and each computer looks at the address; the receiver copies the data and marks the frame as received.","m":1},{"t":"The frame reaches the sender again, which removes the data from the ring.","m":1},{"t":"The sender then releases a new free token, so the next computer can send.","m":1}]},{"id":"cs-12-09-15","kind":"short","q":"What is protocol ?","marks":3,"src":["Guide ch.9 Networking Technology, Q.15"],"model":[{"t":"A protocol is a set of rules that computers follow to talk to each other on a network.","m":1},{"t":"The rules say the form of the data, the order of sending, how errors are found and how the connection starts and ends.","m":1},{"t":"Examples: TCP/IP, HTTP, FTP.","m":1}]},{"id":"cs-12-09-16","kind":"short","q":"What is TCP/IP ?","marks":4,"src":["Guide ch.9 Networking Technology, Q.16"],"model":[{"t":"TCP/IP is the set of protocols (rules) on which the Internet works.","m":1},{"t":"TCP (Transmission Control Protocol) breaks the data into small packets, checks that they arrive and joins them in the right order.","m":1},{"t":"IP (Internet Protocol) gives every computer an address (IP address) and sends each packet along the way to that address.","m":1},{"t":"Because all networks follow TCP/IP, computers of different kinds can talk to each other.","m":1}]},{"id":"cs-12-09-17","kind":"short","q":"What is modem ?","marks":3,"src":["Guide ch.9 Networking Technology, Q.17"],"model":[{"t":"Modem means modulator-demodulator. It is a device that connects a computer to a telephone line.","m":1},{"t":"It changes (modulates) the digital data of the computer into analog signals for the telephone line, and changes (demodulates) the analog signals back into digital data at the other end.","m":1},{"t":"It is used for Internet connections and its speed is in bits per second.","m":1}]},{"id":"cs-12-09-18","kind":"short","q":"What are hubs ? State their types.","marks":4,"src":["Guide ch.9 Networking Technology, Q.18"],"model":[{"t":"A hub is a device with many ports. It joins the computers of a network in a star topology.","m":1},{"t":"A signal that comes into one port is sent out to all the other ports.","m":1},{"t":"Passive hub: only joins the cables and needs no power; it does not regenerate the signal.","m":1},{"t":"Active hub: needs power and regenerates (strengthens) the signal as well; an intelligent hub also has network management features.","m":1}]},{"id":"cs-12-09-19","kind":"short","q":"What is purpose of repeater in network ?","marks":3,"src":["Guide ch.9 Networking Technology, Q.19"],"model":[{"t":"A repeater receives a weak signal, makes it strong again (regenerates and amplifies it) and sends it on.","m":1},{"t":"A signal becomes weak when it travels a long way on a cable (attenuation). So a repeater is used to extend the length of the network.","m":1},{"t":"It works only with signals; it does not look at the addresses of the data.","m":1}]},{"id":"cs-12-09-20","kind":"short","q":"What are routers ? State and explain types of routers.","marks":5,"src":["Guide ch.9 Networking Technology, Q.20"],"model":[{"t":"A router is a device that joins two or more different networks and sends data packets from one network to another.","m":1},{"t":"It reads the destination address of a packet, looks it up in its routing table and chooses the best path.","m":1},{"t":"Static router: the routes are entered by hand and do not change by themselves; it is simple but needs manual changes.","m":1},{"t":"Dynamic router: it learns the routes by talking to other routers and changes them automatically if a path fails.","m":1},{"t":"A router also helps to join a LAN to the Internet.","m":1}]},{"id":"cs-12-09-m21a","kind":"mcq","q":"UTP category 3 uses ........... twisted pair (s) of cables.","marks":1,"src":["Guide ch.9 Networking Technology, Q.21(a)"],"options":["1","2","4","8"],"ans":2,"why":"A UTP category 3 cable has four twisted pairs of wires (although 10BASE-T uses only two of them for data)."},{"id":"cs-12-09-m21b","kind":"mcq","q":"The transmission rate for fiber - optic cable is typically .............","marks":1,"src":["Guide ch.9 Networking Technology, Q.21(b)"],"options":["10 Mbps","25 Mbps","100 Mbps","500 Mbps"],"ans":2,"why":"Among the given choices, the typical rate of fiber optic cable in the syllabus is 100 Mbps."},{"id":"cs-12-09-m21c","kind":"mcq","q":".......... cable type is ideal for connection between two buildings.","marks":1,"src":["Guide ch.9 Networking Technology, Q.21(c)"],"options":["UTP","STP","coaxial","fiber - optic."],"ans":3,"why":"Between buildings the cable must go a long way and may meet electrical noise; fiber optic cable is not affected by it and carries the signal far."},{"id":"cs-12-09-m21d","kind":"mcq","q":"The maximum size of 10 BASE 5 network is .........","marks":1,"src":["Guide ch.9 Networking Technology, Q.21(d)"],"options":["100 meters","300 meters","1500 meters","2500 meters"],"ans":3,"why":"A 10BASE5 network can be up to 2500 metres with repeaters (each segment is 500 metres)."},{"id":"cs-12-09-m21f","kind":"mcq","q":"............. is also called \"Fast ethernet\".","marks":1,"src":["Guide ch.9 Networking Technology, Q.21(f)"],"options":["10 BASE - T","10 BASE - 5","100 VG - Any LAN","100 BASE - X"],"ans":3,"why":"Fast Ethernet works at 100 Mbps and is the 100BASE-X family (100BASE-TX and 100BASE-FX). 10BASE-T and 10BASE-5 are 10 Mbps."},{"id":"cs-12-09-m21g","kind":"mcq","q":"............. converts digital data to analog form.","marks":1,"src":["Guide ch.9 Networking Technology, Q.21(g)"],"options":["Repeater","MODEM","Router","Hub"],"ans":1,"why":"A modem (modulator-demodulator) changes digital data into analog signals and back."},{"id":"cs-12-09-m21h","kind":"mcq","q":"The range of network cabling is extended by .........","marks":1,"src":["Guide ch.9 Networking Technology, Q.21(h)"],"options":["Modem","Repeater","Router","Hub"],"ans":1,"why":"A repeater regenerates the signal, so the cable can be longer."},{"id":"cs-12-09-p901","kind":"mcq","q":"Bandwidth of telephone line is ..........","marks":1,"src":["HSC March 2022 Paper II, Q.1A(d)"],"options":["3 to 4 KHz","30 to 40 KHz","10 to 100 KHz","50 to 80 KHz"],"ans":0,"why":"A voice telephone line carries about 3 to 4 KHz."},{"id":"cs-12-09-p902","kind":"mcq","q":"The most expensive cable amongst the following is............","marks":1,"src":["HSC March 2023 Paper II, Q.1A(c)"],"options":["UTP","Fiber Optic","Co-axial","STP"],"ans":1,"why":"Fibre optic cable costs most (cable, connectors and equipment). UTP is the cheapest."},{"id":"cs-12-09-p903","kind":"mcq","q":"The device used to extend cable length of a computer network is","marks":1,"src":["HSC March 2024 Paper II, Q.1A(d)"],"options":["Modem","Hub","Repeater","Router"],"ans":2,"why":"A repeater regenerates the signal, so the cable can be longer than its normal limit."},{"id":"cs-12-09-p904","kind":"short","q":"What do you mean by Modem ? Explain its types.","marks":3,"src":["HSC March 2022 Paper II, Q.2A(b)"],"model":[{"t":"A modem (modulator-demodulator) changes the digital data of a computer to analog signals for a telephone line, and changes the received analog signals back to digital data.","m":1},{"t":"Types by place: internal modem (a card inside the computer) and external modem (a separate box joined by a cable).","m":1},{"t":"Types by use: dial-up modem (ordinary telephone line, slow), ADSL or broadband modem (fast, uses telephone line at a higher frequency), and wireless (cellular) modem.","m":1}]},{"id":"cs-12-09-p905","kind":"short","q":"Explain any four characteristics of Co-axial Cable.","marks":4,"src":["HSC March 2022 Paper II, Q.2B(b)"],"model":[{"t":"Construction: a copper core, an insulator, a metal braid or foil shield, and an outer plastic cover.","m":1},{"t":"Bandwidth and speed: it has a higher bandwidth than twisted pair, so it carries more data (10 Mbps and more).","m":1},{"t":"Interference: the shield keeps electromagnetic interference and crosstalk low.","m":1},{"t":"Cost and distance: it costs more than twisted pair but less than fibre, and the signal can go 185 to 500 metres without a repeater (thinnet and thicknet).","m":1}]},{"id":"cs-12-09-p906","kind":"short","q":"Compare the characteristics of UTP Cable and STP Cable.","marks":4,"src":["HSC March 2022 Paper II, Q.3B(a)","HSC March 2024 Paper II, Q.3A(a)"],"model":[{"t":"Shielding: UTP (unshielded twisted pair) has no metal shield. STP (shielded twisted pair) has a metal foil or braid around the pairs.","m":1},{"t":"Interference: UTP picks up more noise and crosstalk. STP is better protected from electromagnetic interference.","m":1},{"t":"Cost and size: UTP is cheaper, thinner and easy to install. STP is costlier, thicker and harder to install (it must be grounded).","m":1},{"t":"Use: UTP is used in most office LANs (Ethernet, telephone). STP is used where there is much noise, for example in factories.","m":1}]},{"id":"cs-12-09-p907","kind":"short","q":"Explain LAN, WAN and MAN.","marks":3,"src":["HSC March 2022 Paper II, Q.4A(c)"],"model":[{"t":"LAN (local area network): joins computers in one room, building or campus (up to a few km). It is fast, low cost and privately owned.","m":1},{"t":"MAN (metropolitan area network): covers a city or town (up to about 50 km), for example a cable TV network or the network of a bank in a city.","m":1},{"t":"WAN (wide area network): covers countries or the whole world, uses telephone lines, leased lines or satellites, and is slower and costlier. The Internet is the largest WAN.","m":1}]},{"id":"cs-12-09-p908","kind":"short","q":"Explain Repeater and Router.","marks":4,"src":["HSC March 2022 Paper II, Q.4B(b)"],"model":[{"t":"Repeater: a device that receives a weak signal, cleans and amplifies it and sends it on. It extends the length of a cable. It works at the physical layer and knows no addresses.","m":1},{"t":"A repeater joins two segments of the same type of network, and passes all the traffic, including errors.","m":1},{"t":"Router: a device that joins different networks and sends the packets by the best path, using the network (IP) address. It works at the network layer.","m":1},{"t":"A router can join networks of different types, filters traffic, and is used to connect a LAN to the Internet.","m":1}]},{"id":"cs-12-09-p909","kind":"short","q":"Explain the following characteristics of transmission media\ni) Cost of Media\nii) Electromagnetic interference\niii) Band width","marks":3,"src":["HSC March 2023 Paper II, Q.1B(b)"],"model":[{"t":"Cost of media: the cost of the cable, the connectors and the installation. UTP is the cheapest and fibre optic the costliest.","m":1},{"t":"Electromagnetic interference (EMI): noise from motors, power lines and other cables that spoils the signal. Fibre optic is not affected by it; UTP is the most affected.","m":1},{"t":"Bandwidth: the range of frequencies the medium can carry, which decides how much data per second it can pass. Fibre has the highest, twisted pair the lowest.","m":1}]},{"id":"cs-12-09-p910","kind":"short","q":"Write a short note on Co-axial Cable.","marks":3,"src":["HSC March 2023 Paper II, Q.2A(a)"],"model":[{"t":"A co-axial cable has a central copper wire, an insulating layer, a metal shield (braid or foil) and an outer plastic jacket, all on the same axis.","m":1},{"t":"Types: thinnet (10BASE2, 185 m, RG-58) and thicknet (10BASE5, 500 m, RG-8). It has a higher bandwidth and less interference than twisted pair.","m":1},{"t":"It is used for cable TV and older Ethernet networks, and costs more than twisted pair.","m":1}]},{"id":"cs-12-09-p911","kind":"short","q":"Write the difference between LAN and WAN (Any three points) :","marks":3,"src":["HSC March 2023 Paper II, Q.2A(c)"],"model":[{"t":"Area: LAN covers a small area such as a building or campus. WAN covers a large area such as a country or the world.","m":1},{"t":"Speed and cost: LAN is fast and cheap to set up. WAN is slower and costlier.","m":1},{"t":"Ownership and media: a LAN is owned by one organisation and uses its own cables. A WAN uses public lines (telephone, satellite) and is owned by many.","m":1}]},{"id":"cs-12-09-p912","kind":"short","q":"Write a short note on 'Modem'","marks":4,"src":["HSC March 2023 Paper II, Q.2B(b)"],"model":[{"t":"Modem means modulator-demodulator. It joins a computer to a telephone line.","m":1},{"t":"Modulation: it changes the digital data from the computer into analog signals that can travel on the line.","m":1},{"t":"Demodulation: it changes the analog signals received back into digital data for the computer.","m":1},{"t":"Types: internal and external modems, and dial-up and broadband (ADSL) modems. The speed is measured in bits per second (bps).","m":1}]},{"id":"cs-12-09-p913","kind":"prog","q":"Write a short note on STAR topology using following points :","marks":4,"src":["HSC March 2023 Paper II, Q.4B(b)"],"model":[{"t":"The printed paper does not give the points. The usual ones are: description, diagram, advantages and disadvantages.","m":1},{"t":"Description: in the star topology every computer is joined by its own cable to a central device (hub or switch). All data passes through it.","m":1},{"t":"Advantages: a fault in one cable or computer does not stop the others; easy to add a computer and easy to find a fault.","m":1},{"t":"Disadvantages: if the hub fails the whole network stops; it needs more cable. The diagram: one centre box with lines going to the computers.","m":1}],"code":"         PC1\n          |\n  PC4 --- HUB --- PC2\n          |\n         PC3"},{"id":"cs-12-09-p914","kind":"prog","q":"What is Ring Topology ? Draw neat labelled diagram to show Ring Topology. State one advantage and one disadvantage of Ring Topology.","marks":4,"src":["HSC March 2024 Paper II, Q.2B(b)"],"model":[{"t":"In ring topology the computers are joined one after another in a closed circle; each computer is joined to exactly two neighbours, and data travels round in one direction (often with a token).","m":1},{"t":"Diagram: computers (nodes) placed on a circle with arrows between them.","m":1},{"t":"Advantage: every computer gets an equal chance to send data (token), so there are few collisions.","m":1},{"t":"Disadvantage: if one computer or cable breaks, the whole ring stops (unless it has a second ring).","m":1}],"code":"     PC1 ------> PC2\n      ^            |\n      |            v\n     PC4 <------ PC3"},{"id":"cs-12-09-p915","kind":"short","q":"Explain following connectivity devices:\ni) Modem\nii) Hub","marks":4,"src":["HSC March 2024 Paper II, Q.3B(a)"],"model":[{"t":"Modem: changes digital data to analog signals and back, so a computer can use a telephone line. It joins a computer to the Internet.","m":1},{"t":"Modem types: internal or external, dial-up or broadband.","m":1},{"t":"Hub: a central device with many ports that joins the computers of a star network. A signal received on one port is sent out on all other ports.","m":1},{"t":"A hub does not choose a path, so all computers share the bandwidth. Types: passive, active and intelligent hubs.","m":1}]}];
